using System;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Threading.Tasks;using System.Windows.Forms;
internal sealed class EffectsPreview:Control {
 readonly WallpaperLayerCache layers=new WallpaperLayerCache();public EffectSettings Regions;public Bitmap Picture;public bool WhiteText=true;public EffectsPreview(){DoubleBuffered=true;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(Color.FromArgb(25,29,34));if(Picture==null)return;var state=g.Save();g.SetClip(ClientRectangle);double scale=Math.Max(Width/(double)Picture.Width,Height/(double)Picture.Height);float w=(float)(Picture.Width*scale),h=(float)(Picture.Height*scale);g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(Picture,(Width-w)/2,(Height-h)/2,w,h);g.Restore(state);if(Regions!=null){layers.Draw(g,Picture,Regions,new RectangleF(0,0,Width/4,Height),new SizeF(Width,Height),0);layers.Draw(g,Picture,Regions,new RectangleF(Width/4,Height*3/4,Width-Width/4,Height/4),new SizeF(Width,Height),2);Color color=ColorTranslator.FromHtml(Regions.Color);using(var friend=new SolidBrush(Color.FromArgb((int)(Regions.Friends*2.55),ColorTranslator.FromHtml(BackgroundEffects.RegionColor(Regions,0)))))g.FillRectangle(friend,0,0,Width/4,Height);using(var messages=new SolidBrush(Color.FromArgb((int)(Regions.Chat*2.55),color)))g.FillRectangle(messages,Width/4,Height/8,Width-Width/4,Height*5/8);using(var input=new SolidBrush(Color.FromArgb((int)(Regions.Input*2.55),ColorTranslator.FromHtml(BackgroundEffects.RegionColor(Regions,2)))))g.FillRectangle(input,Width/4,Height*3/4,Width-Width/4,Height/4);}using(var brush=new SolidBrush(WhiteText?Color.White:Color.Black)){g.DrawString("会话标题 · 预览文字",Font,brush,18,20);g.DrawString("这是一段文字，用来比较背景可读性。",Font,brush,18,Height-66);g.DrawString("头像、表情与消息图片不受这些处理影响",Font,brush,18,Height-40);}}
 protected override void Dispose(bool disposing){if(disposing){layers.Dispose();if(Picture!=null){Picture.Dispose();Picture=null;}}base.Dispose(disposing);}
}
internal sealed class EffectsDialog:Form {
 readonly string previewSource;EffectSettings template=new EffectSettings();
 readonly EffectsPreview preview=new EffectsPreview();readonly TrackBar brightness=new TrackBar(),blur=new TrackBar(),tint=new TrackBar();readonly Label bValue=new Label(),rValue=new Label(),tValue=new Label(),status=new Label();readonly Button tintColor=new Button(),apply=new Button();readonly CheckBox automatic=new CheckBox();readonly Timer debounce=new Timer();readonly ToolTip tips=new ToolTip();readonly Bitmap source;readonly double previewScale;int friends,chat,input,header,navigation;string color;bool syncing,busy,pending;
 public EffectsDialog(string selectedSource=null){previewSource=selectedSource;Text="背景可读性";Font=new Font("Microsoft YaHei UI",10);BackColor=Color.FromArgb(246,248,250);ClientSize=new Size(940,530);MinimumSize=MaximumSize=Size;StartPosition=FormStartPosition.CenterParent;MaximizeBox=false;var borderButton=new Button{Text="输入区边框…",Location=new Point(548,20),Size=new Size(178,32)};Controls.Add(borderButton);borderButton.Click+=delegate{using(var dialog=new InputDialog())dialog.ShowDialog(this);};var regions=new Button{Text="分区与色调…",Location=new Point(740,20),Size=new Size(178,32)};regions.Enabled=NativeBackground.WholeEnabled;if(!regions.Enabled)regions.Text="分区需开启整窗背景";Controls.Add(regions);regions.Click+=delegate{using(var dialog=new RegionEffectsDialog(Current()))if(dialog.ShowDialog(this)==DialogResult.OK)LoadValues(dialog.Value);};string path=previewSource??AutoBackground.SavedImage();if(path==null)throw new InvalidOperationException("请先选择并应用一张背景图片。");using(var original=Image.FromFile(path)){previewScale=Math.Min(1,600d/original.Width);source=new Bitmap(Math.Max(1,(int)(original.Width*previewScale)),Math.Max(1,(int)(original.Height*previewScale)));using(var g=Graphics.FromImage(source)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(original,0,0,source.Width,source.Height);}}Controls.Add(new Label{Text="调整背景，让文字更清楚",Font=new Font(Font.FontFamily,17,FontStyle.Bold),Location=new Point(22,18),Size=new Size(500,36)});Controls.Add(new Label{Text="只处理壁纸，保留原图；窗口缩放仍由微信原生绘制。",Location=new Point(22,62),Size=new Size(890,26),ForeColor=Color.FromArgb(85,99,112)});preview.SetBounds(22,104,500,330);preview.Font=Font;Controls.Add(preview);var ink=new CheckBox{Text="预览使用白字",Checked=true,Location=new Point(22,447),Size=new Size(200,28)};Controls.Add(ink);ink.CheckedChanged+=delegate{preview.WhiteText=ink.Checked;preview.Invalidate();};Controls.Add(new Label{Text="分区位置为示意，以微信实际布局为准。",Location=new Point(22,481),Size=new Size(500,24),ForeColor=Color.FromArgb(85,99,112)});
 AddSlider("背景亮度",brightness,bValue,20,150,104,"100% 保留原亮度，降低亮度更适合白字。");AddSlider("模糊程度",blur,rValue,0,12,194,"0 保留清晰原图；少量模糊可减少细节干扰。");AddSlider("蒙版强度",tint,tValue,0,80,284,"混合所选颜色，仅写入背景图片。");tintColor.Text="选择蒙版颜色";tintColor.SetBounds(548,374,180,32);Controls.Add(tintColor);tintColor.Click+=delegate{using(var picker=new StudioColorPicker{FullOpen=true,Color=ColorTranslator.FromHtml(color)})if(picker.ShowDialog(this)==DialogResult.OK){color=String.Format("#{0:X2}{1:X2}{2:X2}",picker.Color.R,picker.Color.G,picker.Color.B);Changed();}};var preset=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(742,374),Size=new Size(176,32)};preset.Items.AddRange(new object[]{"选择可读性预设","清晰暗化","柔和背景","浅色衬底"});preset.SelectedIndex=0;Controls.Add(preset);preset.SelectedIndexChanged+=delegate{if(preset.SelectedIndex==1)LoadValues(new EffectSettings{Brightness=75,Tint=20});else if(preset.SelectedIndex==2)LoadValues(new EffectSettings{Brightness=85,Blur=3,Tint=15});else if(preset.SelectedIndex==3)LoadValues(new EffectSettings{Tint=40,Color="#FFFFFF"});};automatic.Text="拖动结束后自动应用到微信";automatic.SetBounds(548,418,370,28);Controls.Add(automatic);automatic.CheckedChanged+=delegate{if(automatic.Checked)debounce.Start();else debounce.Stop();};apply.Text="保存并应用";apply.SetBounds(548,459,180,36);Controls.Add(apply);apply.Click+=async delegate{debounce.Stop();await ApplySettings();};var reset=new Button{Text="恢复未处理原图",Location=new Point(742,459),Size=new Size(176,36)};Controls.Add(reset);reset.Click+=async delegate{LoadValues(new EffectSettings());debounce.Stop();await ApplySettings();};status.SetBounds(548,500,370,24);Controls.Add(status);debounce.Interval=700;debounce.Tick+=async delegate{debounce.Stop();await ApplySettings();};LoadValues(BackgroundEffects.Load());FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;status.Text="正在更新背景，请稍候。";}};
 }
 void AddSlider(string title,TrackBar bar,Label value,int min,int max,int y,string tip){Controls.Add(new Label{Text=title,Location=new Point(548,y),Size=new Size(230,24)});value.SetBounds(810,y,108,24);value.TextAlign=ContentAlignment.TopRight;Controls.Add(value);bar.Minimum=min;bar.Maximum=max;bar.TickStyle=TickStyle.None;bar.SetBounds(540,y+30,384,42);bar.AccessibleName=title;Controls.Add(bar);tips.SetToolTip(bar,tip);bar.ValueChanged+=delegate{Changed();};}
 EffectSettings Current(){var s=template.Copy();s.Brightness=brightness.Value;s.Blur=blur.Value;s.Tint=tint.Value;s.Color=color;s.Friends=friends;s.Chat=chat;s.Input=input;s.Header=header;s.Navigation=navigation;return s;}
 void LoadValues(EffectSettings s){template=s.Copy();syncing=true;brightness.Value=s.Brightness;blur.Value=s.Blur;tint.Value=s.Tint;color=s.Color;friends=s.Friends;chat=s.Chat;input=s.Input;header=s.Header;navigation=s.Navigation;preview.WhiteText=AppearanceProfiles.Mode==1;syncing=false;Changed();}
 void Changed(){if(syncing)return;bValue.Text=brightness.Value+"%";rValue.Text=blur.Value==0?"关闭":blur.Value.ToString();tValue.Text=tint.Value+"%";tintColor.BackColor=ColorTranslator.FromHtml(color);tintColor.ForeColor=(tintColor.BackColor.R*.299+tintColor.BackColor.G*.587+tintColor.BackColor.B*.114)<135?Color.White:Color.Black;var settings=Current();preview.Regions=settings.Copy();settings.Blur=(int)Math.Round(settings.Blur*previewScale);var next=BackgroundEffects.Transform(source,settings);var old=preview.Picture;preview.Picture=next;if(old!=null)old.Dispose();preview.Invalidate();status.Text="预览已更新；原图仍保留。";if(automatic.Checked){debounce.Stop();debounce.Start();}}
 async Task ApplySettings(){if(busy){pending=true;return;}busy=true;apply.Enabled=false;try{var settings=Current();string selected=previewSource??AutoBackground.SavedImage();if(selected==null)throw new IOException("请先选择并应用背景图片。");BackgroundEffects.Save(settings);status.Text="正在更新微信背景…";for(int attempt=0;;attempt++){bool retry=false;try{await Task.Run(()=>NativeBackground.Apply(selected));break;}catch(IOException e){if(attempt>=4||!e.Message.Contains("另一项背景操作"))throw;retry=true;}if(retry)await Task.Delay(600);}status.Text=settings.Original?"已恢复未处理原图。":"设置已保存并应用。";}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;tips.SetToolTip(status,e.Message);}finally{busy=false;apply.Enabled=true;if(pending){pending=false;debounce.Start();}}}
 internal void SetDraft(EffectSettings s){LoadValues(s);}
 internal EffectSettings Draft(){return Current();} internal void SaveDraftOnly(){BackgroundEffects.Save(Current());}
 public bool OperationBusy{get{return busy;}}public Task ApplyWorkspace(){debounce.Stop();return ApplySettings();} public void RenderForTest(string path){StartPosition=FormStartPosition.Manual;Location=new Point(-30000,-30000);ShowInTaskbar=false;LoadValues(new EffectSettings{Brightness=75,Tint=20});Show();Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(path);}Close();}
 protected override void Dispose(bool disposing){if(disposing){debounce.Dispose();tips.Dispose();if(source!=null)source.Dispose();}base.Dispose(disposing);}
}

